package com.nexodb.db;

import com.nexodb.model.*;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

public final class VisualToolsTest {
    public static void main(String[] args)throws Exception{
        Path driver=Path.of("build/h2-test.jar").toAbsolutePath();ConnectionProfile profile=new ConnectionProfile("visual-test","Test",DatabaseType.H2,"",0,"mem:visual","sa","jdbc:h2:mem:visual;DB_CLOSE_DELAY=-1","org.h2.Driver",driver.toString(),false);
        try(JdbcSession session=JdbcSession.open(profile,new char[0])){
            session.execute("CREATE TABLE customers(id INT PRIMARY KEY,name VARCHAR(100),note VARCHAR(100),\"what?\" VARCHAR(50))",10);session.execute("CREATE TABLE orders(id INT PRIMARY KEY,customer_id INT,amount DECIMAL(10,2),FOREIGN KEY(customer_id) REFERENCES customers(id))",10);
            session.execute("INSERT INTO customers VALUES(1,'snow','leopard','literal?'),(2,'Joe','100%_','nothing'),(3,'snow leopard','other','text')",10);session.execute("INSERT INTO orders VALUES(1,1,10),(2,1,20),(3,2,30)",10);
            String sql=VisualQuery.select(DatabaseType.H2,"\"","PUBLIC",List.of(new VisualQuery.Table("CUSTOMERS","c"),new VisualQuery.Table("ORDERS","o")),List.of(new VisualQuery.Join("c","ID","o","CUSTOMER_ID","LEFT")),List.of(new VisualQuery.Field("c","NAME",true,"","customer","ASC",""),new VisualQuery.Field("o","AMOUNT",true,"SUM","total","",">= 10")),false,50);
            var result=session.execute(sql,100);equal(2,result.rows().size());equal("Joe",result.rows().get(0).get(0));equal("30.00",result.rows().get(0).get(1).toString());
            equal(true,VisualQuery.select(DatabaseType.SQLSERVER,"\"","",List.of(new VisualQuery.Table("x","a")),List.of(),List.of(),false,10).startsWith("SELECT TOP 10"));
            equal(true,VisualQuery.select(DatabaseType.ORACLE,"\"","",List.of(new VisualQuery.Table("x","a")),List.of(),List.of(),false,10).contains("FETCH FIRST 10 ROWS ONLY"));
            equal(false,VisualQuery.joinTypes(DatabaseType.MYSQL).contains("FULL"));equal(true,VisualQuery.joinTypes(DatabaseType.H2).contains("FULL"));String full=VisualQuery.select(DatabaseType.H2,"\"","PUBLIC",List.of(new VisualQuery.Table("CUSTOMERS","c"),new VisualQuery.Table("ORDERS","o")),List.of(new VisualQuery.Join("c","ID","o","CUSTOMER_ID","FULL")),List.of(),false,0);contains(full,"FULL JOIN");reject(()->VisualQuery.select(DatabaseType.MYSQL,"`","test",List.of(new VisualQuery.Table("a","a"),new VisualQuery.Table("b","b")),List.of(new VisualQuery.Join("a","id","b","id","FULL")),List.of(),false,0));
            createTableDialects(session);
            check(session,"snow leopard",2);check(session,"\"snow leopard\"",1);check(session,"Joe OR snow",3);check(session,"snow -other",1);check(session,"100%_",1);check(session,"x' OR 1=1 --",0);
            var odd=DataSearch.condition(DatabaseType.H2,"\"",List.of("what?"),"literal?");String inline=DataSearch.inline(DatabaseType.H2,odd);equal(1,session.execute("SELECT * FROM customers WHERE "+inline,10).rows().size());
            equal(true,DataSearch.literal(DatabaseType.MYSQL,"a'\\;DROP").startsWith("CONVERT(X'"));
        }
        System.out.println("VisualToolsTest: OK (visual queries/search and dialect-aware CREATE TABLE options)");
    }
    private static void createTableDialects(JdbcSession session)throws Exception{
        var id=new CreateTableDefinition.Column("id","INT",true,false,true,true,"","",true,false,false,"","identificador","","",false,List.of());
        var name=new CreateTableDefinition.Column("name","VARCHAR(100)",false,false,false,false,"'nuevo'","utf8mb4_bin",false,true,false,"utf8mb4","Nombre visible","","",false,List.of());
        var generated=new CreateTableDefinition.Column("total","DECIMAL(18,2)",false,true,false,false,"","",false,false,false,"","","STORED","price * quantity",true,List.of());
        var state=new CreateTableDefinition.Column("state","ENUM",false,false,false,false,"'PENDING'","",false,false,false,"","","","",false,List.of("PENDING","SENT","O'HARE"));
        String mysql=CreateTableDefinition.createSql(DatabaseType.MYSQL,"`","sales","products",List.of(id,name,generated,state));contains(mysql,"INT UNSIGNED ZEROFILL NOT NULL AUTO_INCREMENT");contains(mysql,"CHARACTER SET `utf8mb4` COLLATE `utf8mb4_bin` BINARY");contains(mysql,"GENERATED ALWAYS AS (price * quantity) STORED");contains(mysql,"COMMENT 'Nombre visible'");contains(mysql,"INVISIBLE");contains(mysql,"ENUM('PENDING','SENT','O''HARE')");
        var h2id=new CreateTableDefinition.Column("id","INTEGER",true,false,true,false,"","",false,false,false,"","","","",false,List.of());var h2name=new CreateTableDefinition.Column("name","VARCHAR(100)",false,false,false,false,"'nuevo'","",false,false,false,"","","","",false,List.of());
        String h2=CreateTableDefinition.createSql(DatabaseType.H2,"\"","PUBLIC","created_visually",List.of(h2id,h2name));contains(h2,"GENERATED BY DEFAULT AS IDENTITY");session.execute(h2,1);session.execute("INSERT INTO \"PUBLIC\".\"created_visually\"(\"name\") VALUES(DEFAULT)",1);equal("nuevo",session.execute("SELECT \"name\" FROM \"PUBLIC\".\"created_visually\"",10).rows().get(0).get(0));
        contains(CreateTableDefinition.createSql(DatabaseType.POSTGRESQL,"\"","public","sample",List.of(new CreateTableDefinition.Column("id","INTEGER",true,false,true,false,"","",false,false,false,"","","","",false,List.of()))),"GENERATED BY DEFAULT AS IDENTITY");
        contains(CreateTableDefinition.createSql(DatabaseType.SQLSERVER,"\"","dbo","sample",List.of(new CreateTableDefinition.Column("id","INT",true,false,true,false,"","",false,false,false,"","","","",false,List.of()))),"IDENTITY(1,1)");
        contains(CreateTableDefinition.createSql(DatabaseType.SQLITE,"\"","main","sample",List.of(new CreateTableDefinition.Column("id","INTEGER",true,false,true,false,"","",false,false,false,"","","","",false,List.of()))),"INTEGER PRIMARY KEY AUTOINCREMENT");
        equal(true,CreateTableDefinition.features(DatabaseType.MYSQL).types().contains("JSON"));equal(false,CreateTableDefinition.features(DatabaseType.POSTGRESQL).unsigned());
    }
    private static void check(JdbcSession s,String text,int count)throws Exception{var condition=DataSearch.condition(DatabaseType.H2,"\"",List.of("NAME","NOTE"),text);try(var statement=s.connection().prepareStatement("SELECT * FROM customers WHERE "+condition.sql())){for(int i=0;i<condition.parameters().size();i++)statement.setString(i+1,condition.parameters().get(i));int rows=0;try(var result=statement.executeQuery()){while(result.next())rows++;}equal(count,rows);}equal(count,s.execute("SELECT * FROM customers WHERE "+DataSearch.inline(DatabaseType.H2,condition),10).rows().size());}
    private static void contains(String value,String expected){if(!value.contains(expected))throw new AssertionError("Missing ["+expected+"] in ["+value+"]");}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Expected operation to be rejected");}catch(IllegalArgumentException expected){}}
    private static void equal(Object expected,Object actual){if(!Objects.equals(expected,actual))throw new AssertionError("Expected ["+expected+"] got ["+actual+"]");}
}
